local BridgeMaker = {}
local PRODUCTS = {
    iron_bridge = { name = "Železni mostiček za glasbila", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni mostiček za glasbila za glasbila." },
    bronze_bridge = { name = "Bronast mostiček za glasbila", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast mostiček za glasbila za fino glasbo." },
    silver_bridge = { name = "Srebrn mostiček za glasbila", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn mostiček za glasbila za plemiške glasbenike." },
    gilded_bridge = { name = "Pozlačen mostiček za glasbila", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen mostiček za glasbila za dvorne glasbenike." },
    jewel_set_bridge = { name = "Draguljast mostiček za glasbila", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast mostiček za glasbila za kraljevske glasbenike." },
    royal_sovereign_bridge = { name = "Kraljevski suveren mostiček za glasbila", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren mostiček za glasbila z biseri za krono." },
}
local BUILDINGS = {
    bridge_workshop = { name = "Bridge delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bridge_house = { name = "Bridge hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bridge_atelier = { name = "Mojstrski bridge atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bridge_palace = { name = "Suverena bridge palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BridgeMaker.ironStock = 12; BridgeMaker.bronzeStock = 10; BridgeMaker.woodStock = 18; BridgeMaker.leatherStock = 10; BridgeMaker.silverStock = 8; BridgeMaker.goldStock = 6; BridgeMaker.jewelStock = 4; BridgeMaker.pearlStock = 4
BridgeMaker.productStock = {}; BridgeMaker.buildings = {}; BridgeMaker.maker = nil; BridgeMaker.activeMaking = {}; BridgeMaker.totalProducts = 0; BridgeMaker.dayTimer = 0
function BridgeMaker.init() BridgeMaker.ironStock=12; BridgeMaker.bronzeStock=10; BridgeMaker.woodStock=18; BridgeMaker.leatherStock=10; BridgeMaker.silverStock=8; BridgeMaker.goldStock=6; BridgeMaker.jewelStock=4; BridgeMaker.pearlStock=4; BridgeMaker.productStock={}; BridgeMaker.buildings={}; BridgeMaker.maker=nil; BridgeMaker.activeMaking={}; BridgeMaker.totalProducts=0; BridgeMaker.dayTimer=0; print("[BridgeMaker] Royal Bridge Maker System initialized (6 products, 4 buildings)") end
function BridgeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BridgeMaker.maker={name=n or ("Mostičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mostičar najet: %s (spretnost: %d)",BridgeMaker.maker.name,s),"success") end; return true end
function BridgeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BridgeMaker.build(id) local ok,e=BridgeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BridgeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BridgeMaker.getQualityBonus() local b=0; for _,bd in ipairs(BridgeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BridgeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BridgeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BridgeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BridgeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BridgeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BridgeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BridgeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BridgeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BridgeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BridgeMaker.buildings==0 then return false,"Potrebna mostična delavnica" end; if not BridgeMaker.maker then return false,"Potreben mosticar" end; return true end
function BridgeMaker.make(pt,qty) qty=qty or 1; local ok,e=BridgeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BridgeMaker.ironStock=BridgeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BridgeMaker.bronzeStock=BridgeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BridgeMaker.woodStock=BridgeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BridgeMaker.leatherStock=BridgeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BridgeMaker.silverStock=BridgeMaker.silverStock-d.silverCost*qty end; if d.goldCost then BridgeMaker.goldStock=BridgeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BridgeMaker.jewelStock=BridgeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BridgeMaker.pearlStock=BridgeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BridgeMaker.maker then t=math.max(1,t-math.floor(BridgeMaker.maker.skill/13)) end; table.insert(BridgeMaker.activeMaking,{id="bridge_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BridgeMaker.completeMaking(m) local q=1.0+(BridgeMaker.getQualityBonus()/100); if BridgeMaker.maker then q=q+(BridgeMaker.maker.skill/140) end; q=math.min(2.5,q); BridgeMaker.productStock[m.productType]=(BridgeMaker.productStock[m.productType] or 0)+m.quantity; BridgeMaker.totalProducts=BridgeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BridgeMaker.maker then BridgeMaker.maker.itemsMade=BridgeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BridgeMaker.maker.skill=math.min(100,BridgeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mostiček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bridge.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BridgeMaker.update(dt) if not _G.state then return end; BridgeMaker.dayTimer=BridgeMaker.dayTimer+dt; if BridgeMaker.dayTimer>=30 then BridgeMaker.dayTimer=0; for i=#BridgeMaker.activeMaking,1,-1 do local m=BridgeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BridgeMaker.completeMaking(m); table.remove(BridgeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BridgeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BridgeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BridgeMaker.getStats() return {ironStock=BridgeMaker.ironStock,bronzeStock=BridgeMaker.bronzeStock,woodStock=BridgeMaker.woodStock,leatherStock=BridgeMaker.leatherStock,silverStock=BridgeMaker.silverStock,goldStock=BridgeMaker.goldStock,jewelStock=BridgeMaker.jewelStock,pearlStock=BridgeMaker.pearlStock,productStock=BridgeMaker.productStock,numBuildings=#BridgeMaker.buildings,hasMaker=BridgeMaker.maker~=nil,makerName=BridgeMaker.maker and BridgeMaker.maker.name or "—",makerSkill=BridgeMaker.maker and BridgeMaker.maker.skill or 0,activeMaking=#BridgeMaker.activeMaking,totalProducts=BridgeMaker.totalProducts} end
return BridgeMaker
